def transform(grid):
    h, w = len(grid), len(grid[0])
    # The colored grid is encoded at intersections of the regularly spaced
    # horizontal and vertical separator lines. Infer their periods from the
    # repeated separator pattern.
    def line_positions(axis):
        n = h if axis == 0 else w
        vals = [grid[i][0] if axis == 0 else grid[0][i] for i in range(n)]
        candidates = []
        for p in range(2, 8):
            for phase in range(p):
                score = sum(vals[i] != vals[0] for i in range(n) if i % p == phase)
                candidates.append((score, p, phase))
        return min(candidates)[1:]

    # These patterns have separator periods 4/5 or 5/6. Detect separator
    # lines as rows/columns that are mostly unlike the repeated interior.
    def period(n, getline):
        best = None
        for p in range(2, 8):
            for phase in range(p):
                lines = [getline(i) for i in range(n) if i % p == phase]
                if not lines:
                    continue
                # separator lines have unusually low uniformity
                uniform = sum(max(line.count(v) for v in set(line)) / len(line)
                              for line in lines) / len(lines)
                score = (uniform, -len(lines), p, phase)
                if best is None or score < best:
                    best = score
        return best[2], best[3]

    rp, rphase = period(h, lambda r: grid[r])
    cp, cphase = period(w, lambda c: [grid[r][c] for r in range(h)])
    rs = list(range(rphase, h, rp))
    cs = list(range(cphase, w, cp))
    # Drop the trailing boundary marker, which is not part of the encoded array.
    if rs and rs[-1] >= h - rp:
        rs = rs[:-1]
    if cs and cs[-1] >= w - cp:
        cs = cs[:-1]
    return [[grid[r][c] for c in cs] for r in rs]
